def _allowed(user: Dict[str, Any], permission: str) -> bool:
    if user.get('role') == 'Administrateur':
        return True
    permissions = user.get('permissions') or {}
    if permission == 'kacel_job_view':
        return any((bool(permissions.get(key)) for key in ('kacel_job_view', 'kacel_job_manage_companies', 'kacel_job_manage_conventions')))
    return bool(permissions.get(permission))

def _require(user: Dict[str, Any], permission: str) -> None:
    if not _allowed(user, permission):
        raise HTTPException(status_code=403, detail="Vous n'avez pas l'autorisation nécessaire pour Kacel Job.")

def _date_or_none(value: Any, label: str) -> Optional[str]:
    raw = str(value or '').strip()
    if not raw:
        return
    try:
        return date.fromisoformat(raw).isoformat()
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=f'La date « {label} » est invalide.') from exc

def _excel_date(value: Any, label: str) -> Optional[str]:
    if value is None or str(value).strip() == '':
        return
    if isinstance(value, datetime):
        return value.date().isoformat()
    if isinstance(value, date):
        return value.isoformat()
    raw = str(value).strip()
    for fmt in ('%d/%m/%Y', '%d-%m-%Y', '%Y-%m-%d', '%Y/%m/%d'):
        return datetime.strptime(raw, fmt).date().isoformat()
    raise ValueError(f'Date invalide pour {label} : {raw}')

def _normalize_excel_header(value: Any) -> str:
    raw = unicodedata.normalize('NFKD', str(value or '').strip().lower())
    return ''.join((char for char in raw.encode('ascii', 'ignore').decode('ascii') if char.isalnum()))

def _format_tariff(config: Dict[str, Any], mode: str) -> str:
    def money(value: Any) -> str:
        if value in (None, ''):
            return 'À définir'
        try:
            return f'{float(value):,.2f}'.replace(',', ' ').replace('.', ',')
        except (TypeError, ValueError):
            return str(value)

    unit = str(config.get('unit') or 'DA HT')
    if mode == 'discount':
        return f'{money(config.get('percent'))} % de remise'
    if mode == 'headcount_tiers':
        return f'< 10 salariés : {money(config.get('under_10'))} DA HT/jour ; 10 à 25 : {money(config.get('from_10_to_25'))} DA HT/jour ; > 25 : {money(config.get('over_25'))} DA HT/jour'
    if mode == 'company_size_tiers':
        return f'Petite : {money(config.get('small'))} DA HT ; Moyenne : {money(config.get('medium'))} DA HT ; Grande : {money(config.get('large'))} DA HT'
    if mode == 'custom_unit':
        return f'Par bureau : {money(config.get('office'))} DA HT ; par poste : {money(config.get('workstation'))} DA HT'
    return f'{money(config.get('amount'))} {unit}'

