@kacel_job_router.get('/conventions/{convention_id}/pdf')
async def api_convention_pdf(convention_id: int, request: Request):
    user = get_current_user(request)
    _require(user, 'kacel_job_view')
    convention = manager.get_convention(convention_id)
    if not convention:
        raise HTTPException(status_code=404, detail='Convention introuvable.')
    company = manager.get_company(int(convention['entreprise_id']))
    tariffs = manager.get_convention_tariffs(convention_id)
    employees = manager.get_employees(int(convention['entreprise_id']))
    pdf = _build_convention_pdf(convention, company or {}, tariffs, employees)
    reference = ''.join((char for char in str(convention.get('reference') or convention_id) if char.isalnum() or char in '-_'))
    track_action(request, 'KACEL_JOB_PDF_CONVENTION', f'PDF de la convention {reference} consulté')
    return Response(content=pdf, media_type='application/pdf', headers={'Content-Disposition': f'inline; filename="Convention_{reference}.pdf"', 'Cache-Control': 'no-store'})

