@kacel_job_router.post('/employees/import')
async def api_import_employees(request: Request, entreprise_id: int=Form(...), file: UploadFile=File(...)):
    user = get_current_user(request)
    _require(user, 'kacel_job_manage_companies')
    if openpyxl is None:
        raise HTTPException(status_code=500, detail='L’import Excel nécessite la bibliothèque openpyxl.')
    if not file.filename or not file.filename.lower().endswith('.xlsx'):
        raise HTTPException(status_code=400, detail='Choisissez un fichier Excel .xlsx.')
    file_bytes = await file.read()
    if not file_bytes:
        raise HTTPException(status_code=400, detail='Le fichier Excel est vide.')
    try:
        workbook = openpyxl.load_workbook(io.BytesIO(file_bytes), read_only=True, data_only=True)
        worksheet = workbook.active
        values = worksheet.iter_rows(values_only=True)
    except Exception as exc:
        raise HTTPException(status_code=400, detail='Le fichier Excel ne peut pas être lu.') from exc
    try:
        pass
    except Exception as exc:
        raise HTTPException(status_code=400, detail='Le fichier Excel ne peut pas être lu.') from exc
    try:
        headers = [_normalize_excel_header(value) for value in next(values, ())]
    except Exception as exc:
        raise HTTPException(status_code=400, detail='Le fichier Excel ne peut pas être lu.') from exc
    aliases = {'nom': {'nom', 'lastname', 'familyname', 'nomemploye'}, 'prenom': {'prenom', 'firstname', 'givenname'}, 'date_naissance': {'birthdate', 'naissance', 'datenaissance'}, 'date_embauche': {'embauche', 'hiredate', 'dateembauche'}, 'poste': {'job', 'post', 'poste', 'title', 'emploi', 'fonction'}}
    columns = {field: next((index for index, header in enumerate(headers) if header in names), None) for field, names in aliases.items()}
    if columns['nom'] is None or columns['prenom'] is None:
        raise HTTPException(status_code=400, detail='La première ligne doit contenir au minimum les colonnes Nom et Prénom.')
    imported_rows = []
    errors = []
    for row_number, row in enumerate(values, start=2):
        if row:
            if not any((str(value).strip() for value in row)):
                continue
        def cell(field: str) -> Any:
            index = columns[field]
            if index is not None:
                if index < len(row):
                    return row[index]

        nom = str(cell('nom') or '').strip()
        prenom = str(cell('prenom') or '').strip()
        if nom and not prenom:
            errors.append(f'Ligne {row_number} : nom ou prénom manquant.')
            continue
        try:
            imported_rows.append({'nom': nom, 'prenom': prenom, 'date_naissance': _excel_date(cell('date_naissance'), 'date de naissance'), 'date_embauche': _excel_date(cell('date_embauche'), 'date d’embauche'), 'poste': str(cell('poste') or '').strip()})
        except ValueError as exc:
            errors.append(f'Ligne {row_number} : {exc}')
            continue
    workbook.close()
    if errors:
        raise HTTPException(status_code=400, detail='Import annulé. ' + ' '.join(errors[:8]))
    count = manager.import_employees(entreprise_id, imported_rows)
    track_action(request, 'KACEL_JOB_IMPORT_EMPLOYES', f'{count} employé(s) importé(s) dans l’entreprise #{entreprise_id}')
    return {'success': True, 'imported': count}

